window.docContents[157].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--Working-with-Numerals":{"contents":"We know from our definitions above that one is just succ zero,\ntwo is succ one, and so on. We can write rules for these equalities too:\n\ntheorem one_eq_succ_zero : one = succ zero := by rfl\ntheorem two_eq_succ_one : two = succ one := by rfl\ntheorem three_eq_succ_two : three = succ two := by rfl\ntheorem four_eq_succ_three : four = succ three := by rfl\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Rewriting","header":"2.4.7. Working with Numerals","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Rewriting--Working-with-Numerals"},"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Counting":{"contents":"\n\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.2.7. Counting","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Counting"},"/Logic/#Logical-Foundations--Logic-in-Lean--Logical-Connectives":{"contents":"\n\n\n\n\n\n","context":"Logical Foundations\u0009Logic in Lean","header":"8.2. Logical Connectives","id":"/Logic/#Logical-Foundations--Logic-in-Lean--Logical-Connectives"}});